/*
  Output smoothing — global spatial + temporal filter over the composed frame buffer.
  See docs/design/output-smoothing.md
*/
#include "wled.h"

#ifndef WLED_DISABLE_OUTPUT_SMOOTHING

#include "output_smoothing.h"
#include <math.h>

// AI: below section was generated by an AI

// Average two packed WRGB colors without 8-bit byte access (SWAR).
static inline uint32_t colorAvg2(uint32_t a, uint32_t b) {
  return (((a ^ b) & 0xFEFEFEFEu) >> 1) + (a & b);
}

// Binomial 3-tap [1 2 1]/4 via two averages: avg(avg(a,c), b).
static inline uint32_t colorBlur121(uint32_t a, uint32_t b, uint32_t c) {
  return colorAvg2(colorAvg2(a, c), b);
}

// Pack one 8-bit channel into 8.8 fixed-point half of a uint32_t word (low or high).
static inline uint32_t chTo88(uint8_t v) { return (uint32_t)v << 8; }

// One-pole step on a single 8.8 channel. Guarantees progress of at least 1 when target differs.
static inline uint16_t iirStep(uint16_t state, uint16_t target, uint16_t alphaQ15) {
  int32_t diff = (int32_t)target - (int32_t)state;
  if (diff == 0) return state;
  int32_t step = (diff * (int32_t)alphaQ15) >> 15;
  if (step == 0) step = (diff > 0) ? 1 : -1;
  return (uint16_t)((int32_t)state + step);
}

void OutputSmoother::setTargets(uint8_t spatial, uint8_t temporal) {
  if (spatial > SMOOTH_SPATIAL_MAX) spatial = SMOOTH_SPATIAL_MAX;
  if (temporal > SMOOTH_TEMPORAL_MAX) temporal = SMOOTH_TEMPORAL_MAX;
  // Rising edge of either channel: re-seed history so old content does not fade in.
  if ((spatial > 0 || temporal > 0) && (_spatial == 0 && _temporal == 0)) _needsReset = true;
  if (temporal > 0 && _temporal == 0) _needsReset = true;
  _spatial = spatial;
  _temporal = temporal;
  if (temporal == 0) _allocFailed = false; // allow retry after user turns temporal back on
}

void OutputSmoother::reset() {
  _needsReset = true;
}

void OutputSmoother::freeHistory() {
  p_free(_hist);
  _hist = nullptr;
  _histLen = 0;
}

void OutputSmoother::ensureHistory(unsigned len) {
  if (_hist && _histLen == len) return;
  freeHistory();
  if (len == 0) return;
  // 2 stages × 2 uint32_t per pixel (R|G and B|W as 8.8). Prefer PSRAM; 32-bit access only.
  size_t bytes = (size_t)len * SMOOTH_TEMPORAL_STAGES * 2 * sizeof(uint32_t);
  _hist = static_cast<uint32_t*>(allocate_buffer(bytes, BFRALLOC_NOBYTEACCESS | BFRALLOC_PREFER_PSRAM | BFRALLOC_CLEAR));
  if (!_hist) {
    _allocFailed = true;
    errorFlag = ERR_NORAM_PX;
    DEBUG_PRINTF_P(PSTR("OutputSmoother: hist alloc failed (%u B)\n"), (unsigned)bytes);
    return;
  }
  _histLen = len;
  _needsReset = true;
  _allocFailed = false;
}

void OutputSmoother::seedHistory(const uint32_t *px, unsigned len) {
  if (!_hist || len > _histLen) return;
  for (unsigned i = 0; i < len; i++) {
    uint32_t c = px[i];
    uint32_t rg = chTo88(R(c)) | (chTo88(G(c)) << 16);
    uint32_t bw = chTo88(B(c)) | (chTo88(W(c)) << 16);
    // Both stages start at the current frame so the cascade has no step response on enable.
    _hist[i * 4 + 0] = rg;
    _hist[i * 4 + 1] = bw;
    _hist[i * 4 + 2] = rg;
    _hist[i * 4 + 3] = bw;
  }
  _needsReset = false;
}

// In-place 1D blur along a strided sequence. weight 255 = full [1 2 1]/4; 0 = no-op.
// Edge pixels replicate the border value.
void OutputSmoother::blur1D(uint32_t *px, unsigned len, unsigned stride, uint8_t weight) const {
  if (len < 2 || weight == 0) return;
  uint32_t prev = px[0];
  uint32_t curr = px[0];
  for (unsigned i = 0; i < len; i++) {
    uint32_t next = (i + 1 < len) ? px[(i + 1) * stride] : curr;
    uint32_t blurred = colorBlur121(prev, curr, next);
    uint32_t out = (weight == 255) ? blurred : color_blend(curr, blurred, weight);
    px[i * stride] = out;
    prev = curr;
    curr = next;
  }
}

void OutputSmoother::blurSpatial(uint32_t *px, unsigned width, unsigned height, unsigned len) const {
  uint8_t spatial = _spatial;
  if (spatial == 0 || !px || len == 0) return;

  // sigma = spatial/10; variance = sigma^2 = spatial^2/100
  // Full binomial pass variance = 1/2 → nFull = floor(2*sigma^2) = floor(spatial^2/50)
  unsigned nFull = ((unsigned)spatial * (unsigned)spatial) / 50;
  if (nFull > SMOOTH_SPATIAL_MAX_PASSES) nFull = SMOOTH_SPATIAL_MAX_PASSES;
  // Remaining variance → fractional weight w with var(w) = w/2 (w in 0..1)
  // remVar = sigma^2 - nFull/2 = (spatial^2 - nFull*50)/100
  // w = 2*remVar → wQ8 = (spatial^2 - nFull*50) * 255 / 50
  unsigned remNum = (unsigned)spatial * (unsigned)spatial - nFull * 50;
  uint8_t fracW = (uint8_t)((remNum * 255) / 50);
  if (fracW > 255) fracW = 255;

  const bool is2D = (height > 1 && width > 1);
  const unsigned matrixLen = is2D ? (width * height) : 0;

  auto pass = [&](uint8_t w) {
    if (w == 0) return;
    if (!is2D) {
      blur1D(px, len, 1, w);
      return;
    }
    // Horizontal then vertical over the matrix region.
    for (unsigned y = 0; y < height; y++) blur1D(px + y * width, width, 1, w);
    for (unsigned x = 0; x < width; x++) blur1D(px + x, height, width, w);
    // Logical pixels past the matrix (rare hybrid setups) get a 1D pass.
    if (len > matrixLen) blur1D(px + matrixLen, len - matrixLen, 1, w);
  };

  for (unsigned n = 0; n < nFull; n++) pass(255);
  pass(fracW);
}

void OutputSmoother::blurTemporal(uint32_t *px, unsigned len, unsigned dtMs) {
  if (!_hist || len == 0 || len > _histLen) return;

  // No time passed: emit current stage-2 state without updating.
  if (dtMs == 0) {
    for (unsigned i = 0; i < len; i++) {
      uint32_t rg2 = _hist[i * 4 + 2];
      uint32_t bw2 = _hist[i * 4 + 3];
      px[i] = RGBW32(((rg2 & 0xFFFF) + 128) >> 8, ((rg2 >> 16) + 128) >> 8,
                     ((bw2 & 0xFFFF) + 128) >> 8, ((bw2 >> 16) + 128) >> 8);
    }
    return;
  }

  // tau (ms) = temporal * 10; two cascaded stages → tauStage = tau/2 = temporal * 5
  unsigned tauStage = (unsigned)_temporal * 5;
  if (tauStage == 0) tauStage = 1;
  if (dtMs > 250) dtMs = 250;

  // alpha = 1 - exp(-dt/tauStage), stored as Q15 (0..32768)
  float alphaF = 1.0f - expf(-(float)dtMs / (float)tauStage);
  if (alphaF < 0.0f) alphaF = 0.0f;
  if (alphaF > 1.0f) alphaF = 1.0f;
  uint16_t alphaQ15 = (uint16_t)(alphaF * 32768.0f + 0.5f);
  if (alphaQ15 > 32768) alphaQ15 = 32768;

  for (unsigned i = 0; i < len; i++) {
    uint32_t c = px[i];
    uint16_t rT = chTo88(R(c));
    uint16_t gT = chTo88(G(c));
    uint16_t bT = chTo88(B(c));
    uint16_t wT = chTo88(W(c));

    // Stage 1
    uint32_t rg1 = _hist[i * 4 + 0];
    uint32_t bw1 = _hist[i * 4 + 1];
    uint16_t r1 = iirStep((uint16_t)(rg1 & 0xFFFF), rT, alphaQ15);
    uint16_t g1 = iirStep((uint16_t)(rg1 >> 16),    gT, alphaQ15);
    uint16_t b1 = iirStep((uint16_t)(bw1 & 0xFFFF), bT, alphaQ15);
    uint16_t w1 = iirStep((uint16_t)(bw1 >> 16),    wT, alphaQ15);
    _hist[i * 4 + 0] = (uint32_t)r1 | ((uint32_t)g1 << 16);
    _hist[i * 4 + 1] = (uint32_t)b1 | ((uint32_t)w1 << 16);

    // Stage 2 tracks stage 1
    uint32_t rg2 = _hist[i * 4 + 2];
    uint32_t bw2 = _hist[i * 4 + 3];
    uint16_t r2 = iirStep((uint16_t)(rg2 & 0xFFFF), r1, alphaQ15);
    uint16_t g2 = iirStep((uint16_t)(rg2 >> 16),    g1, alphaQ15);
    uint16_t b2 = iirStep((uint16_t)(bw2 & 0xFFFF), b1, alphaQ15);
    uint16_t w2 = iirStep((uint16_t)(bw2 >> 16),    w1, alphaQ15);
    _hist[i * 4 + 2] = (uint32_t)r2 | ((uint32_t)g2 << 16);
    _hist[i * 4 + 3] = (uint32_t)b2 | ((uint32_t)w2 << 16);

    px[i] = RGBW32((r2 + 128) >> 8, (g2 + 128) >> 8, (b2 + 128) >> 8, (w2 + 128) >> 8);
  }
}

void OutputSmoother::apply(uint32_t *px, unsigned width, unsigned height, unsigned len, unsigned dtMs) {
  if (!px || len == 0) return;
  uint8_t spatial = _spatial;
  uint8_t temporal = _temporal;
  if (spatial == 0 && temporal == 0) {
    freeHistory();
    return;
  }

  // Spatial first (operates on current frame), then temporal (needs history).
  if (spatial > 0) {
    if (width == 0) width = len;
    if (height == 0) height = 1;
    blurSpatial(px, width, height, len);
  }

  if (temporal > 0 && !_allocFailed) {
    ensureHistory(len);
    if (_hist) {
      if (_needsReset || _histLen != len) seedHistory(px, len);
      else blurTemporal(px, len, dtMs);
    }
  } else if (temporal == 0) {
    freeHistory();
  }
}

// AI: end

#endif // WLED_DISABLE_OUTPUT_SMOOTHING
